import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api'; // Ensure you have a file to make API requests
import './Auth.css';

const Login = () => {
  const [form, setForm] = useState({ email: '', password: '' });
  const [message, setMessage] = useState('');
  const [success, setSuccess] = useState(null);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await api.post('/auth/login', form); // Assuming you have the /auth/login API endpoint
      setSuccess(true);
      setMessage(res.data.message || 'Login successful!');

      // Store the token in localStorage
      localStorage.setItem('token', res.data.token);
      localStorage.setItem('userId', res.data.userId);

      // Redirect to homepage
      setTimeout(() => navigate('/home'), 1500); 
    } catch (err) {
      setSuccess(false);
      setMessage(err.response?.data?.message || 'Login failed');
    }
  };

  return (
    <div className="auth-container">
      <h2>Login</h2>
      <form className="auth-form" onSubmit={handleSubmit}>
        <input type="email" name="email" placeholder="Email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} required />
        <input type="password" name="password" placeholder="Password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} required />
        <button type="submit">Login</button>
      </form>
      {message && (
        <p className={`auth-message ${success ? 'success' : 'error'}`}>
          {message}
        </p>
      )}
    </div>
  );
};

export default Login;
